insert into passages (id, text, difficulty_level, b, active) values
('17f8046b-509e-49e0-a6a2-3fb6fcee62ad', 'Microplastics, tiny plastic fragments smaller than five millimeters in size, have become an increasingly common presence in the world''s oceans, rivers, and even drinking water. These particles originate from a variety of sources, including the gradual breakdown of larger plastic debris, synthetic fibers shed during the washing of clothing, and tiny beads once commonly added to cosmetic products before many countries banned their use. Because microplastics are so small, they are easily ingested by marine organisms ranging from plankton to fish, and there is growing evidence that these particles can accumulate as they move up the food chain, a process scientists call bioaccumulation. Researchers are still working to understand the full health implications of microplastic exposure for both marine life and humans, though some studies have found that the particles can carry harmful chemicals that leach into the tissues of the organisms that consume them. In response to growing public concern, several countries have introduced regulations limiting the use of microplastics in consumer products, and researchers continue to develop new filtration technologies designed to capture these particles before they enter waterways.', 3, 0.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('188abc2b-77e1-422a-af4c-f8f3e60f6e3f', 'sentence_completion', 'The charity''s new campaign aims to ___ awareness about the importance of clean drinking water.', NULL, '[{"id": "c", "text": "raise"}, {"id": "b", "text": "hide"}, {"id": "a", "text": "ignore"}, {"id": "d", "text": "reduce"}]'::jsonb, 0, '{"strategy": "campaign aims to = קמפיין שואף. מה עושה קמפיין למען מודעות?", "correct_reason": "raise = להעלות. קמפיין נועד להעלות מודעות.", "options_analysis": ["נכון! raise = להעלות — מתאים למטרת קמפיין מודעות", "hide = להסתיר — הפוך ממטרת מודעות", "ignore = להתעלם — סותר את מטרת קמפיין", "reduce = להפחית — הפוך ממטרת קמפיין מודעות"]}', 1.42, 0.0, 0.25, 3, 'ai', NULL, true),
('942a348a-c909-4714-a190-4696b9f57eba', 'sentence_completion', 'The company''s outdated equipment began to ___ production, causing frequent delays.', NULL, '[{"id": "d", "text": "speed up"}, {"id": "c", "text": "hinder"}, {"id": "b", "text": "support"}, {"id": "a", "text": "accelerate"}]'::jsonb, 1, '{"strategy": "causing frequent delays = גרם לעיכובים תכופים. מה עושה ציוד מיושן לייצור?", "correct_reason": "hinder = להפריע. ציוד מיושן מפריע לייצור וגורם לעיכובים.", "options_analysis": ["speed up = להאיץ — הפוך מגרימת עיכובים", "נכון! hinder = להפריע — מתאים לגרימת עיכובים תכופים", "support = לתמוך — הפוך מגרימת עיכובים", "accelerate = להאיץ — הפוך מגרימת עיכובים"]}', 1.6, 0.0, 0.25, 3, 'ai', NULL, true),
('8be23659-7398-4cf5-95ff-365f4edc3b0e', 'sentence_completion', 'The teacher''s encouraging words helped to ___ the shy student''s confidence.', NULL, '[{"id": "a", "text": "destroy"}, {"id": "b", "text": "ignore"}, {"id": "c", "text": "boost"}, {"id": "d", "text": "reduce"}]'::jsonb, 2, '{"strategy": "encouraging words helped = מילים מעודדות עזרו. מה עושות מילים מעודדות לביטחון עצמי?", "correct_reason": "boost = להגביר. מילים מעודדות מגבירות ביטחון עצמי.", "options_analysis": ["destroy = להרוס — הפוך מהשפעת מילים מעודדות", "ignore = להתעלם — סותר את קיום המילים המעודדות", "נכון! boost = להגביר — מתאים להשפעת מילים מעודדות", "reduce = להפחית — הפוך מהשפעת מילים מעודדות"]}', 1.49, 0.0, 0.25, 3, 'ai', NULL, true),
('4ddfa79e-9294-4636-9c2f-76cef71b86fa', 'sentence_completion', 'The government''s new regulations ___ businesses to disclose their environmental impact.', NULL, '[{"id": "c", "text": "discourage"}, {"id": "a", "text": "prevent"}, {"id": "d", "text": "forbid"}, {"id": "b", "text": "require"}]'::jsonb, 3, '{"strategy": "new regulations = תקנות חדשות. מה עושות תקנות שדורשות חשיפת מידע?", "correct_reason": "require = דורשות. תקנות שנועדו לחשיפת מידע דורשות זאת.", "options_analysis": ["discourage = מרתיעות — הפוך מדרישה מפורשת", "prevent = מונעות — הפוך מדרישה לחשיפה", "forbid = אוסרות — הפוך מדרישה לחשיפת מידע", "נכון! require = דורשות — מתאים לתקנות שמחייבות גילוי"]}', 1.27, 0.0, 0.25, 3, 'ai', NULL, true),
('c84cb169-afb4-478a-bbf2-a2a11b1ea47c', 'sentence_completion', 'Years of neglect had caused the historic building to ___ significantly.', NULL, '[{"id": "c", "text": "deteriorate"}, {"id": "b", "text": "flourish"}, {"id": "d", "text": "improve"}, {"id": "a", "text": "strengthen"}]'::jsonb, 0, '{"strategy": "years of neglect = שנות הזנחה. מה קורה למבנה שנים רבות מוזנח?", "correct_reason": "deteriorate = להתדרדר. הזנחה ארוכת שנים גורמת להתדרדרות.", "options_analysis": ["נכון! deteriorate = להתדרדר — תוצאה טבעית של הזנחה ארוכה", "flourish = לשגשג — הפוך מהשפעת הזנחה", "improve = להשתפר — הפוך מהשפעת הזנחה", "strengthen = להתחזק — הפוך מהשפעת הזנחה"]}', 1.12, 0.0, 0.25, 3, 'ai', NULL, true),
('ed45b489-a749-42b6-be67-2dc33d89e855', 'sentence_completion', 'The new manager''s calm leadership style helped to ___ tension among team members.', NULL, '[{"id": "d", "text": "create"}, {"id": "b", "text": "ease"}, {"id": "a", "text": "increase"}, {"id": "c", "text": "ignore"}]'::jsonb, 1, '{"strategy": "calm leadership style helped = סגנון הנהגה רגוע עזר. מה עושה מנהיגות רגועה למתח בצוות?", "correct_reason": "ease = להקל. מנהיגות רגועה מקלה על מתח בין חברי צוות.", "options_analysis": ["create = ליצור — הפוך ממטרת הקלת מתח", "נכון! ease = להקל — מתאים להשפעת מנהיגות רגועה", "increase = להגביר — הפוך מהשפעת מנהיגות רגועה", "ignore = להתעלם — סותר את קיום הפעולה שעזרה"]}', 1.26, 0.0, 0.25, 3, 'ai', NULL, true),
('02f2e1d9-93ff-465a-b19f-b4e7131e6342', 'sentence_completion', 'The scientist''s groundbreaking research helped to ___ new possibilities in cancer treatment.', NULL, '[{"id": "b", "text": "ignore"}, {"id": "c", "text": "close off"}, {"id": "d", "text": "open up"}, {"id": "a", "text": "eliminate"}]'::jsonb, 2, '{"strategy": "groundbreaking research helped = מחקר פורץ דרך עזר. מה עושה מחקר פורץ דרך לאפשרויות טיפול?", "correct_reason": "open up = לפתוח. מחקר פורץ דרך פותח אפשרויות חדשות.", "options_analysis": ["ignore = להתעלם — סותר את השפעת המחקר", "close off = לסגור — הפוך מפתיחת אפשרויות", "נכון! open up = לפתוח — מתאים למחקר פורץ דרך שיוצר הזדמנויות", "eliminate = לחסל — הפוך מפתיחת אפשרויות"]}', 1.59, 0.0, 0.25, 3, 'ai', NULL, true),
('54cf1072-7a66-428e-bc4e-0134241cba69', 'sentence_completion', 'The company''s decision to ___ overtime pay led to widespread employee dissatisfaction.', NULL, '[{"id": "b", "text": "offer"}, {"id": "c", "text": "expand"}, {"id": "d", "text": "increase"}, {"id": "a", "text": "eliminate"}]'::jsonb, 3, '{"strategy": "led to widespread employee dissatisfaction = הובילה לחוסר שביעות רצון נרחב. איזו החלטה על שכר שעות נוספות מובילה לתסכול עובדים?", "correct_reason": "eliminate = לבטל. ביטול תשלום שעות נוספות מוביל לתסכול עובדים.", "options_analysis": ["offer = להציע — הפוך מגרימת חוסר שביעות רצון", "expand = להרחיב — הפוך מגרימת חוסר שביעות רצון", "increase = להגדיל — הפוך מגרימת חוסר שביעות רצון", "נכון! eliminate = לבטל — מתאים לגרימת תסכול עובדים"]}', 1.41, 0.0, 0.25, 3, 'ai', NULL, true),
('8f76dbe0-4c52-46f3-8925-b4f5a0db468f', 'sentence_completion', 'The city''s new bike lanes are designed to ___ cycling as a safe transportation option.', NULL, '[{"id": "a", "text": "promote"}, {"id": "b", "text": "ignore"}, {"id": "d", "text": "forbid"}, {"id": "c", "text": "discourage"}]'::jsonb, 0, '{"strategy": "designed to = נועדו ל-. מה מטרת שבילי אופניים חדשים?", "correct_reason": "promote = לקדם. שבילי אופניים נועדו לקדם רכיבה בטוחה.", "options_analysis": ["נכון! promote = לקדם — מתאים למטרת בניית תשתית לרכיבה", "ignore = להתעלם — סותר את מטרת התשתית", "forbid = לאסור — הפוך ממטרת עידוד רכיבה", "discourage = לרפות ידיים — הפוך ממטרת שבילי אופניים"]}', 1.0, 0.0, 0.25, 3, 'ai', NULL, true),
('6940bdca-8f52-41cb-b5fa-0448379d43a5', 'sentence_completion', 'The negotiator''s flexibility helped to ___ a compromise that satisfied both parties.', NULL, '[{"id": "b", "text": "prevent"}, {"id": "c", "text": "reach"}, {"id": "d", "text": "avoid"}, {"id": "a", "text": "block"}]'::jsonb, 1, '{"strategy": "flexibility helped = גמישות עזרה. מה עושה גמישות למשא ומתן שמסתיים בפשרה?", "correct_reason": "reach = להגיע ל-. גמישות עוזרת להגיע לפשרה.", "options_analysis": ["prevent = למנוע — הפוך מהשפעת גמישות חיובית", "נכון! reach = להגיע — מתאים להשפעת גמישות בהשגת פשרה", "avoid = להימנע — הפוך ממטרת הגעה לפשרה", "block = לחסום — הפוך מהשפעת גמישות"]}', 1.57, 0.0, 0.25, 3, 'ai', NULL, true),
('37fbca7a-f4ee-4a31-a63e-bd0dbcf1bb73', 'sentence_completion', 'The company''s poor customer service began to ___ its reputation in the industry.', NULL, '[{"id": "b", "text": "protect"}, {"id": "a", "text": "enhance"}, {"id": "c", "text": "damage"}, {"id": "d", "text": "improve"}]'::jsonb, 2, '{"strategy": "poor customer service = שירות לקוחות גרוע. מה עושה שירות גרוע למוניטין?", "correct_reason": "damage = לפגוע. שירות לקוחות גרוע פוגע במוניטין.", "options_analysis": ["protect = להגן — הפוך מהשפעת שירות גרוע", "enhance = לשפר — הפוך מהשפעת שירות גרוע", "נכון! damage = לפגוע — תוצאה טבעית של שירות לקוחות גרוע", "improve = לשפר — הפוך מהשפעת שירות גרוע"]}', 1.24, 0.0, 0.25, 3, 'ai', NULL, true),
('c3494d16-bd00-4991-a7bd-ddd048be0f5a', 'sentence_completion', 'The teacher''s innovative methods managed to ___ even the most disengaged students.', NULL, '[{"id": "c", "text": "exclude"}, {"id": "b", "text": "ignore"}, {"id": "d", "text": "bore"}, {"id": "a", "text": "engage"}]'::jsonb, 3, '{"strategy": "even the most disengaged students = אפילו התלמידים הכי לא מעורבים. מה עושות שיטות חדשניות לתלמידים לא מעורבים?", "correct_reason": "engage = לערב/למשוך. שיטות חדשניות מצליחות לערב גם תלמידים לא מעורבים.", "options_analysis": ["exclude = להדיר — הפוך ממטרת שיטות שמערבות", "ignore = להתעלם — סותר את פעולת השיטות", "bore = לשעמם — הפוך ממטרת שיטות חדשניות", "נכון! engage = לערב — מתאים להצלחה במשיכת תלמידים לא מעורבים"]}', 1.39, 0.0, 0.25, 3, 'ai', NULL, true),
('a7937316-d0a1-4d7e-9209-d2c765b2f5f7', 'restatement', 'The library extended its hours after receiving numerous requests from students during exam season.', NULL, '[{"id": "d", "text": "In response to many student requests during exam season, the library kept its doors open longer."}, {"id": "b", "text": "The library reduced its hours despite student requests."}, {"id": "c", "text": "No students ever asked the library to change its hours."}, {"id": "a", "text": "The library''s hours have always been the same, regardless of exam season."}]'::jsonb, 0, '{"strategy": "extended hours after requests = הרחיבה שעות אחרי בקשות. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: בתגובה לבקשות רבות, הספרייה נשארה פתוחה יותר זמן", "הפוך — סותר ''extended its hours''", "סותר ''after receiving numerous requests''", "סותר ''extended its hours'' — כן היה שינוי"]}', 1.41, 0.0, 0.25, 3, 'ai', NULL, true),
('ef58d14e-61b7-4f04-91fa-df0ec7e8b16a', 'restatement', 'The company''s stock price plummeted after the CEO abruptly resigned.', NULL, '[{"id": "d", "text": "The CEO never resigned from the company."}, {"id": "b", "text": "Following the CEO''s sudden resignation, the company''s stock price dropped sharply."}, {"id": "a", "text": "The stock price remained completely stable throughout."}, {"id": "c", "text": "The stock price rose sharply after the CEO''s resignation."}]'::jsonb, 1, '{"strategy": "plummeted after abruptly resigned = צנח אחרי התפטרות פתאומית. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''the CEO abruptly resigned''", "נכון! אותה משמעות בדיוק: אחרי התפטרות פתאומית, המניה צנחה בחדות", "הפוך — סותר ''plummeted''", "הפוך — ''rose sharply'' סותר ''plummeted''"]}', 1.23, 0.0, 0.25, 3, 'ai', NULL, true),
('7b705dd9-4bfa-43e2-b78b-40b6fe17364c', 'restatement', 'The farmers adopted new irrigation techniques after suffering severe crop losses due to drought.', NULL, '[{"id": "b", "text": "The drought had no impact on the farmers'' crops."}, {"id": "a", "text": "The farmers had always used the new irrigation techniques."}, {"id": "d", "text": "After experiencing significant crop losses from the drought, the farmers began using new irrigation methods."}, {"id": "c", "text": "The farmers refused to change their irrigation methods despite the drought."}]'::jsonb, 2, '{"strategy": "adopted new techniques after suffering losses = אימצו שיטות חדשות אחרי הפסדים. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''severe crop losses due to drought''", "הפוך — סותר ''adopted new irrigation techniques''", "נכון! אותה משמעות בדיוק: אחרי הפסדי יבול משמעותיים, אימצו שיטות השקיה חדשות", "הפוך — סותר ''adopted new irrigation techniques''"]}', 1.14, 0.0, 0.25, 3, 'ai', NULL, true),
('51bd1155-373d-48e3-b043-91b0aaefc818', 'restatement', 'The airline improved its customer service after facing a wave of complaints on social media.', NULL, '[{"id": "d", "text": "No customers ever complained about the airline."}, {"id": "c", "text": "The airline''s customer service got worse after the complaints."}, {"id": "a", "text": "The airline ignored all complaints and made no changes."}, {"id": "b", "text": "In response to numerous social media complaints, the airline made its customer service better."}]'::jsonb, 3, '{"strategy": "improved after facing complaints = שיפרה אחרי תלונות. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''facing a wave of complaints''", "הפוך — ''worse'' סותר ''improved''", "הפוך — סותר ''improved its customer service''", "נכון! אותה משמעות בדיוק: בתגובה לתלונות רבות, שירות הלקוחות השתפר"]}', 1.11, 0.0, 0.25, 3, 'ai', NULL, true),
('ba65c431-bddc-4dc7-be2d-572aeaef5d2a', 'restatement', 'The town''s economy rebounded quickly after the new factory opened and created hundreds of jobs.', NULL, '[{"id": "d", "text": "After the new factory opened and generated hundreds of jobs, the town''s economy quickly recovered."}, {"id": "c", "text": "The town''s economy collapsed after the new factory opened."}, {"id": "b", "text": "The factory closed down shortly after opening."}, {"id": "a", "text": "The new factory created no jobs at all."}]'::jsonb, 0, '{"strategy": "economy rebounded after factory created jobs = כלכלה התאוששה אחרי יצירת מקומות עבודה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: אחרי פתיחת המפעל ויצירת מאות משרות, הכלכלה התאוששה מהר", "הפוך — ''collapsed'' סותר ''rebounded''", "סותר ''the new factory opened''", "הפוך — סותר ''created hundreds of jobs''"]}', 1.44, 0.0, 0.25, 3, 'ai', NULL, true),
('d35576e7-a383-4ad0-ac55-645d00e739c3', 'restatement', 'The theater canceled the show after several key cast members fell ill.', NULL, '[{"id": "b", "text": "The show was a huge success as planned."}, {"id": "c", "text": "Because multiple important cast members became sick, the theater called off the show."}, {"id": "d", "text": "All the cast members remained perfectly healthy."}, {"id": "a", "text": "The theater proceeded with the show despite the illness of cast members."}]'::jsonb, 1, '{"strategy": "canceled after key members fell ill = ביטלה אחרי שחברים מרכזיים חלו. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''canceled the show''", "נכון! אותה משמעות בדיוק: מכיוון שכמה שחקנים מרכזיים חלו, בוטלה ההצגה", "הפוך — סותר ''fell ill''", "הפוך — סותר ''canceled the show''"]}', 1.57, 0.0, 0.25, 3, 'ai', NULL, true),
('85536ee9-e8bc-4e6e-ba64-6bea8c016eb9', 'restatement', 'The neighborhood organized a cleanup event after residents complained about accumulating litter.', NULL, '[{"id": "c", "text": "The litter problem disappeared on its own without any action."}, {"id": "d", "text": "The neighborhood decided against holding any cleanup event."}, {"id": "a", "text": "In response to complaints about growing litter, the neighborhood held a cleanup event."}, {"id": "b", "text": "Residents never complained about litter in the neighborhood."}]'::jsonb, 2, '{"strategy": "organized cleanup after complaints = ארגנה ניקיון אחרי תלונות. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''accumulating litter'' — הבעיה כן הייתה קיימת", "הפוך — סותר ''organized a cleanup event''", "נכון! אותה משמעות בדיוק: בתגובה לתלונות על פסולת גוברת, השכונה ערכה אירוע ניקיון", "הפוך — סותר ''residents complained''"]}', 1.2, 0.0, 0.25, 3, 'ai', NULL, true),
('49d8e704-413f-49ce-8191-c3bc7291791d', 'restatement', 'The university revised its admissions policy after concerns were raised about fairness.', NULL, '[{"id": "d", "text": "The university refused to change its admissions policy despite the concerns."}, {"id": "c", "text": "The admissions policy remained exactly the same."}, {"id": "b", "text": "No concerns were ever raised about the admissions policy."}, {"id": "a", "text": "After fairness concerns were brought up, the university changed its admissions policy."}]'::jsonb, 3, '{"strategy": "revised policy after concerns raised = תיקנה מדיניות אחרי חששות. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''revised its admissions policy''", "הפוך — סותר ''revised''", "סותר ''concerns were raised about fairness''", "נכון! אותה משמעות בדיוק: אחרי שהועלו חששות בנוגע להגינות, המדיניות שונתה"]}', 1.16, 0.0, 0.25, 3, 'ai', NULL, true),
('d3d19ee3-e157-4db6-966a-3c5c13594fc1', 'restatement', 'The store increased its prices after facing rising costs from suppliers.', NULL, '[{"id": "d", "text": "Due to increasing costs from suppliers, the store raised its prices."}, {"id": "b", "text": "The store never changed its prices at all."}, {"id": "a", "text": "Supplier costs remained exactly the same throughout."}, {"id": "c", "text": "The store lowered its prices despite rising supplier costs."}]'::jsonb, 0, '{"strategy": "increased prices after rising costs = העלתה מחירים אחרי עליית עלויות. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: בגלל עליית עלויות מספקים, החנות העלתה מחירים", "הפוך — סותר ''increased its prices''", "הפוך — סותר ''rising costs from suppliers''", "הפוך — ''lowered'' סותר ''increased''"]}', 1.28, 0.0, 0.25, 3, 'ai', NULL, true),
('2faf9cb4-df9a-418c-bd76-9c7eca799242', 'restatement', 'The company launched a loyalty program after noticing a decline in repeat customers.', NULL, '[{"id": "c", "text": "No loyalty program was ever created by the company."}, {"id": "d", "text": "Having noticed fewer repeat customers, the company introduced a loyalty program."}, {"id": "a", "text": "The company canceled its loyalty program due to a decline in customers."}, {"id": "b", "text": "The company never experienced any decline in repeat customers."}]'::jsonb, 1, '{"strategy": "launched program after noticing decline = השיקה תוכנית אחרי ירידה. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''launched a loyalty program''", "נכון! אותה משמעות בדיוק: לאחר ירידה בלקוחות חוזרים, השיקה תוכנית נאמנות", "הפוך — סותר ''launched a loyalty program''", "הפוך — סותר ''a decline in repeat customers''"]}', 1.22, 0.0, 0.25, 3, 'ai', NULL, true),
('3bd0bfed-a73c-4a36-a12b-46798380b04a', 'restatement', 'The airport expanded its runway after air traffic increased significantly over the past decade.', NULL, '[{"id": "c", "text": "Air traffic decreased significantly over the past decade."}, {"id": "a", "text": "The airport''s runway has remained unchanged for decades."}, {"id": "d", "text": "Because air traffic grew substantially over the last ten years, the airport made its runway longer."}, {"id": "b", "text": "The airport reduced the size of its runway."}]'::jsonb, 2, '{"strategy": "expanded runway after traffic increased = הרחיב מסלול אחרי עליית תעבורה. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''air traffic increased significantly''", "הפוך — סותר ''expanded''", "נכון! אותה משמעות בדיוק: מכיוון שתעבורה אווירית גדלה משמעותית, המסלול הוארך", "הפוך — סותר ''expanded its runway''"]}', 1.55, 0.0, 0.25, 3, 'ai', NULL, true),
('71c300b3-0809-4fb7-904d-a3644c759f0b', 'restatement', 'The school implemented a new anti-bullying program after several incidents were reported by students.', NULL, '[{"id": "a", "text": "No incidents were ever reported to the school."}, {"id": "c", "text": "The anti-bullying program existed long before any incidents occurred."}, {"id": "b", "text": "The school refused to address any bullying incidents."}, {"id": "d", "text": "After students reported multiple incidents, the school put a new anti-bullying program in place."}]'::jsonb, 3, '{"strategy": "implemented program after incidents reported = יישמה תוכנית אחרי דיווחים. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''several incidents were reported''", "הפוך — סותר את סדר האירועים הכרונולוגי", "הפוך — סותר ''implemented a new anti-bullying program''", "נכון! אותה משמעות בדיוק: אחרי שתלמידים דיווחו על תקריות רבות, הופעלה תוכנית חדשה"]}', 1.1, 0.0, 0.25, 3, 'ai', NULL, true),
('d6ef7c2c-495c-4f56-bd96-faf33e9e43e3', 'reading_comprehension', 'What is the main topic of the passage?', '17f8046b-509e-49e0-a6a2-3fb6fcee62ad', '[{"id": "b", "text": "Microplastics, their sources, and their effects on the environment"}, {"id": "c", "text": "The history of plastic manufacturing"}, {"id": "d", "text": "The benefits of cosmetic products"}, {"id": "a", "text": "How to recycle plastic bottles at home"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה עוסקת במיקרופלסטיק, מקורותיו והשפעותיו.", "correct_reason": "הפסקה סוקרת הגדרה, מקורות, השפעה ביולוגית, ותגובה רגולטורית.", "options_analysis": ["נכון! מיקרופלסטיק, מקורותיו והשפעותיו = הנושא המרכזי", "לא מוזכר בפסקה כלל", "הפוך — הפסקה מזכירה חרוזי קוסמטיקה כמקור לבעיה, לא כתועלת", "לא מוזכר בפסקה כלל"]}', 1.32, 0.0, 0.25, 3, 'ai', NULL, true),
('725e65dd-fa02-44c8-90c2-e68ef1469b55', 'reading_comprehension', 'According to the passage, what are some sources of microplastics?', '17f8046b-509e-49e0-a6a2-3fb6fcee62ad', '[{"id": "c", "text": "Exclusively industrial factory waste"}, {"id": "b", "text": "The breakdown of larger plastic debris, synthetic fibers from clothing, and cosmetic beads"}, {"id": "a", "text": "Only natural ocean processes unrelated to human activity"}, {"id": "d", "text": "Only volcanic eruptions"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את מקורות המיקרופלסטיק בפסקה.", "correct_reason": "הפסקה אומרת: ''originate from a variety of sources, including the gradual breakdown of larger plastic debris, synthetic fibers shed during the washing of clothing, and tiny beads once commonly added to cosmetic products''.", "options_analysis": ["לא נאמר בפסקה — הפסקה מתארת מקורות מגוונים, לא רק תעשייתיים", "נכון! נאמר במפורש בפסקה", "הפוך — המקורות המתוארים קשורים ישירות לפעילות אנושית", "לא נאמר בפסקה כלל"]}', 1.04, 0.0, 0.25, 3, 'ai', NULL, true),
('724f4788-4192-41d0-acc1-5d137bd7687e', 'reading_comprehension', 'The word "ingested" in the passage most closely means:', '17f8046b-509e-49e0-a6a2-3fb6fcee62ad', '[{"id": "b", "text": "rejected"}, {"id": "a", "text": "manufactured"}, {"id": "d", "text": "swallowed or consumed"}, {"id": "c", "text": "destroyed"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''they are easily ingested by marine organisms''.", "correct_reason": "ingested = נבלע/נאכל.", "options_analysis": ["הפוך גמור למשמעות המילה", "לא קשור למשמעות המילה", "נכון! ingested = נבלע/נאכל", "לא קשור למשמעות המילה"]}', 1.37, 0.0, 0.25, 3, 'ai', NULL, true),
('c0c0762c-adde-406e-b4da-b90cedf3fa2f', 'reading_comprehension', 'According to the passage, what is bioaccumulation?', '17f8046b-509e-49e0-a6a2-3fb6fcee62ad', '[{"id": "c", "text": "A type of regulation limiting plastic use"}, {"id": "d", "text": "A method for manufacturing new plastic products"}, {"id": "b", "text": "A technique for cleaning ocean water"}, {"id": "a", "text": "The process by which microplastics accumulate as they move up the food chain"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את הגדרת bioaccumulation בפסקה.", "correct_reason": "הפסקה אומרת: ''these particles can accumulate as they move up the food chain, a process scientists call bioaccumulation''.", "options_analysis": ["לא נאמר בפסקה — זה תהליך ביולוגי, לא רגולציה", "לא נאמר בפסקה כלל", "לא נאמר בפסקה כלל", "נכון! נאמר במפורש בפסקה"]}', 1.12, 0.0, 0.25, 3, 'ai', NULL, true),
('81426d0a-e620-4289-9d59-8e67dc2d2c45', 'reading_comprehension', 'What have some countries done in response to growing public concern about microplastics, according to the passage?', '17f8046b-509e-49e0-a6a2-3fb6fcee62ad', '[{"id": "b", "text": "Introduced regulations limiting the use of microplastics in consumer products"}, {"id": "a", "text": "Ignored the issue completely"}, {"id": "d", "text": "Banned all forms of plastic entirely"}, {"id": "c", "text": "Increased the production of cosmetic beads"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את התגובה הרגולטורית בפסקה.", "correct_reason": "הפסקה אומרת: ''several countries have introduced regulations limiting the use of microplastics in consumer products''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "הפוך — הפסקה מתארת תגובה רגולטורית אקטיבית", "קיצוני מדי ולא נאמר בפסקה", "הפוך גמור — הפסקה מתארת מדינות שאסרו שימוש בחרוזים כאלה"]}', 1.1, 0.0, 0.25, 3, 'ai', NULL, true);